package com.mofy.app.data.library

import androidx.room.migration.Migration
import androidx.sqlite.SQLiteConnection
import androidx.sqlite.execSQL
import com.mofy.app.data.catalog.SyncedCatalogVecDao

/**
 * Room migrations for AppDatabase. The 15 -> 16 DDL below is copied verbatim
 * from the exported schema snapshot (app/schemas/.../16.json, generated by
 * Room's KSP processor with exportSchema=true) rather than hand-written, so
 * it matches exactly what MigrationTestHelper.runMigrationsAndValidate
 * expects. synced_catalog_vec is NOT a Room entity (Room can't model vec0's
 * typed virtual-table columns) - created via raw execSQL, same native
 * extension already loaded on AppDatabase's driver.
 *
 * Overrides migrate(SQLiteConnection), NOT the legacy
 * migrate(SupportSQLiteDatabase) - AppDatabase is built with
 * .setDriver(BundledSQLiteDriver()), and Room's default
 * migrate(SupportSQLiteDatabase) throws NotImplementedError for any
 * driver-based database ("Migration functionality with a provided
 * SQLiteDriver requires overriding the migrate(SQLiteConnection)
 * function.") - this crashed app startup entirely until fixed (caught by
 * an on-device connectedDebugAndroidTest run, not by JVM unit tests or a
 * plain compile, which don't open the real database).
 */
object Migrations {
    val MIGRATION_15_16 = object : Migration(15, 16) {
        override fun migrate(connection: SQLiteConnection) {
            connection.execSQL(
                "CREATE TABLE IF NOT EXISTS `synced_catalog_items` (" +
                    "`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, " +
                    "`tmdbId` INTEGER NOT NULL, " +
                    "`mediaType` TEXT NOT NULL, " +
                    "`title` TEXT NOT NULL, " +
                    "`overview` TEXT NOT NULL, " +
                    "`posterUrl` TEXT, " +
                    "`releaseDate` TEXT, " +
                    "`genres` TEXT, " +
                    "`kind` TEXT NOT NULL, " +
                    "`firstSeenEpochMillis` INTEGER NOT NULL)",
            )
            connection.execSQL(
                "CREATE UNIQUE INDEX IF NOT EXISTS `index_synced_catalog_items_tmdbId_mediaType` " +
                    "ON `synced_catalog_items` (`tmdbId`, `mediaType`)",
            )
            connection.execSQL(
                "CREATE VIRTUAL TABLE IF NOT EXISTS `synced_catalog_search` USING FTS4(" +
                    "`itemId` INTEGER NOT NULL, `title` TEXT NOT NULL, `overview` TEXT NOT NULL)",
            )
            connection.execSQL(SyncedCatalogVecDao.CREATE_TABLE_SQL)
        }
    }

    // 16 -> 17 DDL copied verbatim from app/schemas/.../17.json (ADR 0010 task 1).
    val MIGRATION_16_17 = object : Migration(16, 17) {
        override fun migrate(connection: SQLiteConnection) {
            connection.execSQL(
                "CREATE TABLE IF NOT EXISTS `model_download_state` (" +
                    "`modelKey` TEXT NOT NULL, " +
                    "`status` TEXT NOT NULL, " +
                    "`url` TEXT NOT NULL, " +
                    "`bytesDownloaded` INTEGER NOT NULL, " +
                    "`bytesTotal` INTEGER NOT NULL, " +
                    "`destPath` TEXT NOT NULL, " +
                    "`lastErrorMessage` TEXT, " +
                    "`updatedAtEpochMillis` INTEGER NOT NULL, " +
                    "PRIMARY KEY(`modelKey`))",
            )
        }
    }
}